export function PessimisticUI({
  confirmed = {{confirmed}},
  scenario = "{{scenario}}",
  itemLabel = "{{itemLabel}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <button type="button" disabled={!confirmed} style={{ fontWeight: 700, border: "none", borderRadius: 8, padding: "9px 16px", cursor: confirmed ? "pointer" : "not-allowed", background: confirmed ? accent : "#24143022", color: confirmed ? "#FAF7F2" : "#24143066" }}>{itemLabel}</button>
      {!confirmed && <span role="status" aria-live="polite" style={{ display: "block", marginTop: 10, fontSize: 12 }}>Waiting for the server before updating anything&hellip;</span>}
      {confirmed && <p role="status" style={{ margin: "10px 0 0", fontWeight: 600, color: "#241430" }}>Confirmed &mdash; now the UI updates</p>}
      <p style={{ margin: "10px 0 0", fontSize: 11 }}>Pessimistic: nothing changes on screen until the server replies</p>
    </div>
  );
}
